"""Generate src/audio/aac_tables.rs (AAC-LC Huffman codebooks, scale-factor band offsets, TNS max bands)
from soundkit-aac-lc 0.12.3 (MIT) source files: src/spectral.rs, src/scalefactor.rs, src/sfb.rs, src/tns.rs.
These are the ISO/IEC 14496-3 tables (Huffman codebooks of subclause 4.A.1, swb offsets of 4.5.4,
TNS_MAX_BANDS of 4.6.9.4) as transcribed by that crate. Run once offline."""
import hashlib
import re
import sys

root, out_path = sys.argv[1], sys.argv[2]
files = {name: open(f'{root}/src/{name}', 'rb').read() for name in ['spectral.rs', 'scalefactor.rs', 'sfb.rs', 'tns.rs']}
text = {k: v.decode('utf-8') for k, v in files.items()}


def numbers(src, name):
    m = re.search(r'const ' + re.escape(name) + r'\s*:[^=]*=\s*&?\[', src)
    if not m:
        raise SystemExit('missing ' + name)
    i = m.end() - 1
    depth = 0
    for j in range(i, len(src)):
        if src[j] == '[':
            depth += 1
        elif src[j] == ']':
            depth -= 1
            if depth == 0:
                body = src[i:j + 1]
                break
    body = re.sub(r'//[^\n]*', '', body)
    return [int(v, 0) for v in re.findall(r'0x[0-9a-fA-F]+|\d+', body)]


sp = text['spectral.rs']
books = []  # (id, dim, offset, max_bits, lengths, codes)
pairs = {
    1: ('STANDARD_CODEBOOK_1_2_LENGTHS', 'high', 'STANDARD_CODEBOOK_1_CODES', 4, -1),
    2: ('STANDARD_CODEBOOK_1_2_LENGTHS', 'low', 'STANDARD_CODEBOOK_2_CODES', 4, -1),
    3: ('STANDARD_CODEBOOK_3_4_LENGTHS', 'high', 'STANDARD_CODEBOOK_3_CODES', 4, 0),
    4: ('STANDARD_CODEBOOK_3_4_LENGTHS', 'low', 'STANDARD_CODEBOOK_4_CODES', 4, 0),
    5: ('STANDARD_CODEBOOK_5_6_LENGTHS', 'high', 'STANDARD_CODEBOOK_5_CODES', 2, -4),
    6: ('STANDARD_CODEBOOK_5_6_LENGTHS', 'low', 'STANDARD_CODEBOOK_6_CODES', 2, -4),
    7: ('STANDARD_CODEBOOK_7_8_LENGTHS', 'high', 'STANDARD_CODEBOOK_7_CODES', 2, 0),
    8: ('STANDARD_CODEBOOK_7_8_LENGTHS', 'low', 'STANDARD_CODEBOOK_8_CODES', 2, 0),
    9: ('STANDARD_CODEBOOK_9_10_LENGTHS', 'high', 'STANDARD_CODEBOOK_9_CODES', 2, 0),
    10: ('STANDARD_CODEBOOK_9_10_LENGTHS', 'low', 'STANDARD_CODEBOOK_10_CODES', 2, 0),
    11: ('STANDARD_CODEBOOK_11_LENGTHS', 'raw', 'STANDARD_CODEBOOK_11_CODES', 2, 0),
}
out = []
out.append('// Generated by gen_aac_tables.py from soundkit-aac-lc 0.12.3 (MIT, see crate NOTICE): ISO/IEC 14496-3')
out.append('// Huffman codebooks, scale-factor band offsets and LC TNS_MAX_BANDS. Do not edit by hand.')
for name, raw in files.items():
    out.append(f'// input src/{name} sha256 {hashlib.sha256(raw).hexdigest()}')
out.append('// Included by aac_lc.rs (include!), not a module.')
for cb in range(1, 12):
    lname, half, cname, dim, off = pairs[cb]
    lengths = numbers(sp, lname)
    if half == 'high':
        lengths = [v >> 16 for v in lengths]
    elif half == 'low':
        lengths = [v & 0xFFFF for v in lengths]
    codes = numbers(sp, cname)
    assert len(lengths) == len(codes), (cb, len(lengths), len(codes))
    max_bits = max(lengths)
    entries = [f'({c:#x}, {l})' for c, l in zip(codes, lengths)]
    out.append('#[rustfmt::skip]')
    out.append(f'const CB{cb}: [(u16, u8); {len(entries)}] = [' + ', '.join(entries) + '];')
    out.append(f'const CB{cb}_DIM: usize = {dim};')
    out.append(f'const CB{cb}_OFFSET: i32 = {off};')
    out.append(f'const CB{cb}_SIDE: usize = {round(len(entries) ** (1 / dim))};')

sf = text['scalefactor.rs']
sf_len = numbers(sf, 'STANDARD_SCALE_FACTOR_CODE_LENGTHS')
sf_codes = numbers(sf, 'STANDARD_SCALE_FACTOR_CODES')
assert len(sf_len) == len(sf_codes) == 121
out.append('#[rustfmt::skip]')
out.append('const SF_CODES: [(u32, u8); 121] = [' + ', '.join(f'({c:#x}, {l})' for c, l in zip(sf_codes, sf_len)) + '];')

sfb = text['sfb.rs']
for name in ['SWB_OFFSET_1024_96', 'SWB_OFFSET_1024_64', 'SWB_OFFSET_1024_48', 'SWB_OFFSET_1024_32',
             'SWB_OFFSET_1024_24', 'SWB_OFFSET_1024_16', 'SWB_OFFSET_1024_8', 'SWB_OFFSET_128_96',
             'SWB_OFFSET_128_48', 'SWB_OFFSET_128_24', 'SWB_OFFSET_128_16', 'SWB_OFFSET_128_8']:
    v = numbers(sfb, name)
    out.append('#[rustfmt::skip]')
    out.append(f'const {name}: [u16; {len(v)}] = [' + ', '.join(map(str, v)) + '];')

tns = text['tns.rs']
for name in ['TNS_MAX_BANDS_1024', 'TNS_MAX_BANDS_128']:
    v = numbers(tns, name)
    out.append(f'const {name}: [u8; {len(v)}] = [' + ', '.join(map(str, v)) + '];')
open(out_path, 'w', encoding='utf-8', newline='\n').write('\n'.join(out) + '\n')
print('ok')
